-- Central database (PostgreSQL), migration 1: accounts, devices, sessions, audit.
-- Applied by apps/api/scripts/migrate.py, which records it in schema_migrations.
-- IDs are UUIDs generated by the API (time-ordered v7). Times are timestamptz (UTC).

CREATE TABLE users (
    id             uuid PRIMARY KEY,
    email          text NOT NULL CHECK (email = lower(email) AND length(email) BETWEEN 3 AND 254),
    password_hash  text NOT NULL,
    display_name   text CHECK (display_name IS NULL OR length(display_name) BETWEEN 1 AND 80),
    role           text NOT NULL DEFAULT 'user' CHECK (role IN ('user', 'admin')),
    created_at     timestamptz NOT NULL DEFAULT now(),
    updated_at     timestamptz NOT NULL DEFAULT now(),
    disabled_at    timestamptz
);
CREATE UNIQUE INDEX users_email_key ON users (email);

-- One row per app installation of a user. client_id is the device_id the app
-- generates on first start (settings table on the device).
CREATE TABLE devices (
    id            uuid PRIMARY KEY,
    user_id       uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    client_id     uuid NOT NULL,
    name          text NOT NULL CHECK (length(name) BETWEEN 1 AND 80),
    platform      text NOT NULL CHECK (platform IN ('windows', 'android', 'browser')),
    created_at    timestamptz NOT NULL DEFAULT now(),
    last_seen_at  timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX devices_user_client_key ON devices (user_id, client_id);

-- Refresh tokens are stored as SHA-256 hashes, never in clear. Each refresh
-- rotates the token: the old row gets revoked_at and replaced_by. Presenting a
-- revoked token again means it was copied, so the whole family is revoked.
CREATE TABLE refresh_tokens (
    id           uuid PRIMARY KEY,
    user_id      uuid NOT NULL REFERENCES users (id) ON DELETE CASCADE,
    device_id    uuid NOT NULL REFERENCES devices (id) ON DELETE CASCADE,
    family_id    uuid NOT NULL,
    token_hash   bytea NOT NULL,
    created_at   timestamptz NOT NULL DEFAULT now(),
    expires_at   timestamptz NOT NULL,
    revoked_at   timestamptz,
    replaced_by  uuid REFERENCES refresh_tokens (id) ON DELETE SET NULL
);
CREATE UNIQUE INDEX refresh_tokens_hash_key ON refresh_tokens (token_hash);
CREATE INDEX refresh_tokens_family_idx ON refresh_tokens (family_id);
CREATE INDEX refresh_tokens_user_idx ON refresh_tokens (user_id);

-- Settings that follow the user across devices (filled from Phase 6).
CREATE TABLE user_settings (
    user_id     uuid PRIMARY KEY REFERENCES users (id) ON DELETE CASCADE,
    data        jsonb NOT NULL DEFAULT '{}'::jsonb,
    updated_at  timestamptz NOT NULL DEFAULT now(),
    version     integer NOT NULL DEFAULT 1
);

-- Sign-in attempts, for rate limiting. email is stored lower-cased; old rows
-- can be deleted at any time (only the last 15 minutes are read).
CREATE TABLE auth_attempts (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    email       text NOT NULL,
    ip          text,
    success     boolean NOT NULL,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX auth_attempts_email_time_idx ON auth_attempts (email, created_at DESC);

-- Security-relevant events. Never contains passwords or tokens.
CREATE TABLE audit_log (
    id          bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    user_id     uuid REFERENCES users (id) ON DELETE SET NULL,
    device_id   uuid REFERENCES devices (id) ON DELETE SET NULL,
    action      text NOT NULL,
    ip          text,
    meta        jsonb NOT NULL DEFAULT '{}'::jsonb,
    created_at  timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_log_user_time_idx ON audit_log (user_id, created_at DESC);
